#include <iostream>
#include <cstddef>

struct AccountRecord {
    int accountNumber;
    char name[15];
    double balance;
};

std::size_t calculateOffset(int recordKey, std::size_t recordSize) {
    return static_cast<std::size_t>(recordKey - 1) * recordSize;
}

int main() {
    const std::size_t recordSize = sizeof(AccountRecord);
    std::cout << "Record size: " << recordSize << " bytes\n";

    int requestedKeys[] = {1, 2, 5, 100};
    for (int key : requestedKeys) {
        std::size_t offset = calculateOffset(key, recordSize);
        std::cout << "Account " << key << " -> Offset: " << offset << " bytes\n";
    }
    return 0;
}

#include <iostream>
#include <sstream>
#include <string>
#include <algorithm>

class ClientData {
public:
    ClientData(int accNum = 0, const std::string& last = "",
               const std::string& first = "", double bal = 0.0)
        : accountNumber(accNum), balance(bal) {
        setLastName(last);
        setFirstName(first);
    }

    int getAccountNumber() const { return accountNumber; }
    std::string getLastName() const { return lastName; }
    std::string getFirstName() const { return firstName; }
    double getBalance() const { return balance; }

    void setLastName(const std::string& lastStr) {
        std::size_t len = std::min(lastStr.size(), static_cast<std::size_t>(14));
        lastStr.copy(lastName, len);
        lastName[len] = '\0';
    }

    void setFirstName(const std::string& firstStr) {
        std::size_t len = std::min(firstStr.size(), static_cast<std::size_t>(9));
        firstStr.copy(firstName, len);
        firstName[len] = '\0';
    }

private:
    int accountNumber;
    char lastName[15];
    char firstName[10];
    double balance;
};

int main() {
    // Simulate binary stream using stringstream in binary mode
    std::stringstream stream(std::ios::in | std::ios::out | std::ios::binary);

    ClientData record1(100, "WorthingtonLongName", "Alexander", 245.50);
    std::cout << "ClientData object size: " << sizeof(ClientData) << " bytes\n";

    // Write raw binary record
    stream.write(reinterpret_cast<const char*>(&record1), sizeof(ClientData));

    // Read raw binary record back
    stream.seekg(0, std::ios::beg);
    ClientData record2;
    stream.read(reinterpret_cast<char*>(&record2), sizeof(ClientData));

    std::cout << "Read Account: " << record2.getAccountNumber() << "\n"
              << "Last Name:    " << record2.getLastName() << " (truncated to 14 chars)\n"
              << "First Name:   " << record2.getFirstName() << " (truncated to 9 chars)\n"
              << "Balance:      " << record2.getBalance() << "\n";
    return 0;
}
